Rewrite the following GNU C++11 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to rewrite:
<original_code>
#include <iostream>
using namespace std;
long long N, K;
const long long MOD = 1000000007;
long long Power[65], Res[35][35];
long long S[65][35][35][35], A[65][35][35][35], P[65][35][35][35], Aux[35][35];
pair <long long, long long> X[105];
void copy(long long X[][35], long long Y[][35], long long n)
{
    for(long long i = 0; i < n; i++)
        for(long long j = 0; j < n; j++)
            X[i][j] = Y[i][j];
}
inline void Add(long long& x, long long y)
{
    x += y;
    if(x >= MOD)
        x -= MOD;
}
void mul(long long X[][35], long long Y[][35], long long Z[][35], long long n, long long m, long long p)
{
    for(long long i = 0; i < n; i++)
        for(long long j = 0; j < p; j++)
        {
            Z[i][j] = 0;
            for(long long k = 0; k < m; k++)
            {
                Add(Z[i][j], (1LL * X[i][k] * Y[k][j]) % MOD);
            }
        }
}

void precalcA()
{
    for(long long x = 0; x < K; x++)
    {
        for(long long i = 0; i < K + 1; i++)
                A[0][x][i][i] = 1;
        for(long long j = 0; j < K + 1; j++)
            A[0][x][j][x] = 1;
        //A[0][x][x][x] = 0;
    }
    copy(P[0][0], A[0][0], K + 1);
    copy(S[0][K - 1], A[0][K - 1], K + 1);
    for(long long x = 1; x < K; x++)
    {
        mul(P[0][x - 1], A[0][x], P[0][x], K + 1, K + 1, K + 1);
    }
    for(long long x = K - 2; x >= 0; x--)
    {
        mul(A[0][x], S[0][x + 1], S[0][x], K + 1, K + 1, K + 1);
    }
    long long cnt = 1;
    for(long long m = K; m <= N; m *= K, cnt++)
    {
        for(long long x = 0; x < K; x++)
        {
            if(x > 0)
            {
                copy(A[cnt][x], S[cnt - 1][x], K + 1);
                mul(A[cnt][x], P[cnt - 1][x - 1], Aux, K + 1, K + 1, K + 1);
                copy(A[cnt][x], Aux, K + 1);
            }
            else
                copy(A[cnt][x], S[cnt - 1][x], K + 1);
        }
        copy(P[cnt][0], A[cnt][0], K + 1);
        copy(S[cnt][K - 1], A[cnt][K - 1], K + 1);
        for(long long x = 1; x < K; x++)
        {
            mul(P[cnt][x - 1], A[cnt][x], P[cnt][x], K + 1, K + 1, K + 1);
        }
        for(long long x = K - 2; x >= 0; x--)
        {
            mul(A[cnt][x], S[cnt][x + 1], S[cnt][x], K + 1, K + 1, K + 1);
        }
        if(m > N / K)
            break;
    }
}
int main()
{
    cin >> N >> K;
    Power[0] = 1;
    int i = 1;
    while(Power[i - 1] <= N / K)
    {
        Power[i] = Power[i - 1] * K;
        ++i;
    }
    int ind = i;
    --ind;
    precalcA();
    long long init = N, last = -1, count = -1, ind2 = 0;
    Res[0][K] = 1;
    for(int i = ind; i >= 0; i--)
    {
        while(Power[i] <= init)
        {
            mul(Res, A[i][ind2], Aux, K + 1, K + 1, K + 1);
            copy(Res, Aux, K + 1);
            ind2++;
            if(ind2 == K)
                ind2 = 0;
            init -= Power[i];
        }
    }
    long long ans = 0;
    for(int i = 0; i <= K; i++)
        Add(ans, Res[0][i]);
    cout << ans << "\n";
    return 0;
}

